# Let's fetch expenses for yesterday from all groups to find the ones matching Venmo payments.
all_expenses = []
for g in all_groups:
    gid = g["group_id"]
    exp = apis.splitwise.show_group_expenses(group_id=gid, access_token=sw_token, min_created_at="2023-05-19", max_created_at="2023-05-19", page_limit=20)
    if exp:
        for e in exp:
            e["group_id"] = gid
            e["group_name"] = g["name"]
        all_expenses.extend(exp)
print("Total expenses yesterday:", len(all_expenses))
for e in all_expenses:
    print(e)

